+      'lostSpaceTolerant matches the collapsed screen and the intact one',
+      () {
+        final terminal = Terminal(maxLines: 24 * 4);
+        terminal.write(_redRunRow17);
+        final collapsed = _screenLines(
+          terminal,
+        ).firstWhere((t) => t.contains('round-trip'));
+
