+      final meta = lostSpaceTolerant('step 1 (a.b) done');
+      expect('step 1 (a.b) done', matches(meta));
+      expect('step 1 (aXb) done', isNot(matches(meta)));
+      expect('step1 (a.b)done', matches(meta));
+    });
